-- ---------------------------------------------------------------------------
-- PART 17 OF 23: Objection handling library
--
-- Run the parts in filename order. Each is idempotent on its own, so a part
-- can be re-run safely; running them out of order will fail on a foreign key.
-- ---------------------------------------------------------------------------

begin;

-- ---------------------------------------------------------------------------
-- Objection handling library
-- ---------------------------------------------------------------------------

insert into public.objections (id, slug, objection, translation, category, frequency, acknowledge, clarify, address, close, pitfalls, claim_sensitive, status) values
  ('fecc843b-fd49-5368-88af-e5779ad46d90', 'mahal-naman', 'Mahal naman.', 'That is expensive.', 'price', 'very-high', 'I understand po. Importante talaga na sulit ang bawat piso, especially kung negosyo ang pag-uusapan.', 'May I ask - mahal po ba compared sa budget niyo ngayon, or compared sa ibang supplier na nakita niyo?', 'Kung budget po ang concern: ang starter pack ang pinakamaliit na order namin, kaya mababa ang unang commitment niyo. Kung comparison po sa iba: ang presyo namin ay kasama na ang delivery sa Metro Manila, ang packaging na ready for resale, at ang marketing materials na pwede niyo agad gamitin. Hindi lang po chips ang binabayaran niyo - kasama na ang support para makapagsimula kayo.', 'Gusto niyo po bang i-compute natin ang per-pack cost para makita niyo kung saan papasok ang selling price niyo?', array['Do not immediately offer a discount - you probably cannot authorise it, and it teaches the customer to wait for one.', 'Do not argue that it is "not expensive". You are telling them their judgement is wrong.', 'Do not compare KCO to a named competitor.']::text[], false, 'published'),
  ('fd48a10b-38f0-5a4e-b488-e479ba86c8da', 'baka-hindi-ko-mabenta', 'Baka hindi ko mabenta.', 'I might not be able to sell it.', 'risk', 'very-high', 'Valid po yan, Ms. Rivera. Normal lang mag-alala sa unang order - ayaw naman po natin ma-stuck kayo sa stock.', 'May I ask po - ano ang mas kinakabahan niyo, ang paghahanap ng buyers or ang dami ng stock?', 'Dahil dyan po kami nag-set ng mababang minimum. Sa starter pack, sapat lang po para ma-test niyo kung aling flavour ang mabilis mauubos sa area niyo, hindi yung malaking stock na mahirap ilipat. Bibigyan din po namin kayo ng product photos, captions, at basic selling guide para hindi kayo magsimula sa zero. At kung nauubos po agad, mabilis lang ang resupply.', 'Gusto niyo po bang simulan natin sa pinakamaliit na pack, para test muna, then dagdagan natin pag okay na?', array['Never promise that the stock will definitely sell.', 'Do not dismiss the fear - it is the most reasonable objection on this list.', 'Do not push a larger pack to hit a quota.']::text[], false, 'published'),
  ('315b45b1-161e-5b43-acd9-99bfd0936d49', 'pag-isipan-ko-muna', 'Pag-isipan ko muna.', 'Let me think about it first.', 'timing', 'very-high', 'Of course po - dapat lang na pag-isipan ang anumang investment. Take your time.', 'May I ask lang po, para matulungan ko kayo - ano pong part ang pinag-iisipan niyo? Yung presyo, yung pagbebenta, or kailangan niyo pang kausapin ang partner niyo?', 'Kung presyo po: pwede natin i-break down ang cost per pack. Kung pagbebenta po: may guide kami kung paano magsimula online. Kung may kausapin pa po kayo, i-send ko na lang ang complete details para may maipakita kayo - kasama na ang inclusions at delivery schedule.', 'I-send ko po ang details ngayon. Pwede po ba akong mag-follow up bukas ng hapon para sagutin ang mga tanong niyo?', array['Do not ask "why?" bluntly - it reads as a challenge.', 'Do not invent urgency ("last stock na po") that is not real.', 'Do not ask for the sale again in the same breath.']::text[], false, 'published'),
  ('8e8db757-b563-53e2-ae43-5d4fa226eaed', 'wala-akong-experience', 'Wala akong experience sa negosyo.', 'I have no business experience.', 'capability', 'high', 'Naiintindihan ko po. Marami sa mga reseller namin ay first-timers din nung nagsimula sila.', 'May I ask po - nakapag-sell na po ba kayo online kahit personal items lang, or talagang first time?', 'Hindi po kailangan ng business background para dito. Ang binibigay namin ay ang produkto, ang product photos, ready-to-use captions, at isang simpleng guide kung paano mag-post at sumagot sa tanong ng customer. Ang kailangan lang po sa umpisa ay isang Facebook account at willingness mag-reply sa mga tanong. Meron din po kaming reseller support kung may hindi kayo sigurado.', 'Gusto niyo po bang i-send ko yung starter guide para makita niyo mismo kung gaano kasimple ang proseso?', array['Do not say "madali lang yan" - it minimises a real worry.', 'Do not promise hand-holding that the team cannot actually deliver.']::text[], false, 'published'),
  ('a7a05acd-29f0-5fe0-acc9-cbcfde0cde99', 'wala-akong-physical-store', 'Wala akong physical store.', 'I do not have a physical store.', 'capability', 'high', 'Okay lang po yan - hindi po requirement ang physical store para maging KCO reseller.', 'May I ask po - active po ba kayo sa Facebook or Messenger? Yun po ang pinakamadaling simulan.', 'Malaking parte po ng mga reseller namin ay online lang - Facebook posts, Messenger orders, at meet-up or delivery. Walang rent, walang display shelf. Bibigyan po namin kayo ng photos at captions na pwede niyo agad i-post, at may packaging na kayang i-ship. Kung may sari-sari store naman po ang kakilala niyo, pwede rin kayo mag-supply sa kanila.', 'Gusto niyo po bang i-set up natin ang online starter pack para sa inyo?', array['Do not imply an online seller is a lesser reseller.', 'Do not promise delivery coverage you have not checked.']::text[], false, 'published'),
  ('6f440cc5-80e7-5af6-9da1-51f4f0fe02ba', 'marami-nang-nagbebenta', 'Marami nang nagbebenta ng Kangkong Chips.', 'A lot of people already sell Kangkong Chips.', 'competition', 'high', 'Tama po kayo - sumikat talaga ang kangkong chips, kaya marami ang nag-offer.', 'May I ask po - nakita niyo po ba kung ano ang binebenta nila sa area niyo, at magkano?', 'Dalawa po ang pinag-iba namin. Isa, ang produkto: consistent ang crunch at packaging namin, at may proper labeling - hindi repacked. Dalawa, ang support: bibigyan namin kayo ng marketing materials at reseller pricing na hindi lang basta paubos ng stock. Ang mataas na demand po ay hindi problema - ibig sabihin may market na. Ang mahalaga ay kayo ang may maayos na supply at presentation.', 'Gusto niyo po bang ipakita ko ang product photos at packaging namin para makita niyo ang difference?', array['Never disparage a named competitor or another reseller.', 'Do not claim exclusivity or territory rights unless Admin has confirmed them in writing.']::text[], false, 'published'),
  ('9b39b6e7-6215-507b-a029-c2b9a77151e9', 'may-supplier-na-ako', 'May supplier na ako.', 'I already have a supplier.', 'competition', 'medium', 'Mabuti po yan - ibig sabihin alam niyo na ang proseso ng pag-resupply.', 'May I ask po - kumusta ang supply nila, consistent po ba ang stock at delivery?', 'Hindi po namin kailangang palitan ang supplier niyo agad. Ang ginagawa ng ibang reseller ay ginagamit kami as backup - pag out of stock sila or delayed ang delivery, may mapupuntahan kayo agad. Kung mas okay naman po ang terms namin sa tagal ng panahon, kayo na po ang magdedesisyon. Walang exclusivity requirement po sa amin.', 'Gusto niyo po bang i-send ko ang pricing namin para may comparison kayo, kahit for reference lang muna?', array['Do not ask them to break an existing agreement.', 'Do not ask who their supplier is - it reads as intelligence-gathering.', 'Do not undercut with a price you cannot honour.']::text[], false, 'published'),
  ('c80de4cb-fab2-57d5-bb62-03d5a22235d9', 'wala-akong-malaking-capital', 'Wala akong malaking capital.', 'I do not have a lot of capital.', 'capital', 'very-high', 'Naiintindihan ko po. Hindi po biro ang maglabas ng pera para sa panibagong negosyo.', 'May I ask po - magkano ang comfortable niyong ilabas sa unang order, para makita natin kung kasya?', 'Dahil dyan po ang starter pack ang pinakamababang entry namin - yun po ang minimum na order, hindi yung malaking bulk. Ganun din po ang dahilan kung bakit kasama na ang delivery sa Metro Manila, para walang dagdag na gastos sa umpisa. Wala rin pong franchise fee, membership fee, o bayad sa marketing materials.', 'Gusto niyo po bang tignan natin ang exact na halaga ng starter pack, para malaman niyo kung kasya sa budget niyo ngayon?', array['Never suggest borrowing money or offering a loan.', 'Do not present the purchase as risk-free.', 'Do not quote an instalment scheme unless Finance has approved one in writing.']::text[], false, 'published'),
  ('41f54951-85f1-5286-ad51-64327bbf37b1', 'baka-matagal-ang-roi', 'Baka matagal ang ROI.', 'The return on investment might take a long time.', 'risk', 'medium', 'Magandang tanong po - dapat lang alam niyo kung kailan bumabalik ang pera niyo.', 'May I ask po - ilan ang customer na kayang maabot niyo sa isang linggo, at gaano kadalas kayo makakapag-post?', 'Maging prangka po tayo: depende po ito sa selling price na ilalagay niyo, sa area niyo, at kung gaano kadalas kayo mag-post o mag-alok. Hindi po namin kayang mangako ng specific na panahon. Ang kaya po naming gawin ay tulungan kayong makuha ang tamang selling price at bigyan kayo ng materials para mas mabilis mag-move ang stock. Kung gusto niyo po, i-compute natin ang break-even base sa sarili niyong numbers - pero example lang po ito, hindi guarantee.', 'Gusto niyo po bang i-compute natin nang sabay ang break-even base sa target selling price niyo?', array['Never state or imply a guaranteed payback period.', 'Never quote a "typical" ROI figure that Admin has not approved.', 'Always label any computation as an illustration built from the customer’s own assumptions.']::text[], true, 'published'),
  ('8eb3fbc6-e118-59c8-8123-950b37a8d595', 'hindi-ako-marunong-mag-online-selling', 'Hindi ako marunong mag-online selling.', 'I do not know how to sell online.', 'capability', 'high', 'Okay lang po yan. Marami sa nagsisimula ay ganun din - natutunan lang nila habang nag-post.', 'May I ask po - gumagamit po ba kayo ng Facebook or Messenger sa araw-araw?', 'Kung marunong po kayong mag-post at mag-reply sa Messenger, sapat na po yun para makapagsimula. Bibigyan po namin kayo ng ready na product photos, captions na pwede niyong kopyahin, at simpleng guide kung paano sagutin ang mga karaniwang tanong - presyo, delivery, at flavour. Hindi po kailangan ng website, ads, o technical na kaalaman sa umpisa.', 'Gusto niyo po bang i-send ko yung starter kit ng photos at captions para makita niyo?', array['Do not overwhelm them with ads, SEO, or marketplace jargon.', 'Do not promise training sessions that do not exist.']::text[], false, 'published'),
  ('50ab0508-be11-5f21-b717-5d1916a93ba8', 'baka-hindi-patok-sa-lugar-namin', 'Baka hindi patok sa lugar namin.', 'It might not be popular in our area.', 'market', 'medium', 'Fair po yan - magkaiba talaga ang nagpapatok sa bawat lugar.', 'May I ask po - saan po banda kayo, at ano ang uso pong snack sa area niyo ngayon?', 'Ang pinakamurang paraan po para malaman ay maliit na test order. Yun ang dahilan kung bakit mababa ang minimum namin - para hindi kayo mag-commit sa malaking stock bago malaman kung tatanggapin sa area niyo. Nakakatulong din po na healthier snack ang positioning ng kangkong chips, kaya kadalasan may market sa mga school, office, at sari-sari store. Pero test order po ang magsasabi, hindi ang assumption natin.', 'Gusto niyo po bang simulan sa isang starter pack as test para sa area niyo?', array['Do not claim the product "always sells" anywhere.', 'Do not cite sales figures from another area as a promise.']::text[], true, 'published'),
  ('e0697753-afa6-523c-b813-32e9abc65179', 'magkano-ang-kita-ko', 'Magkano ang kita ko?', 'How much will I earn?', 'price', 'very-high', 'Magandang tanong po - dapat lang malinaw ito bago kayo mag-order.', 'May I ask po - magkano ang balak niyong ipagbenta per pack sa area niyo?', 'Ang kita po ay ang pagitan ng reseller price niyo at ng selling price na ilalagay niyo, less ang gastos niyo sa delivery o packaging. Ibibigay po namin ang exact reseller price at ang suggested retail range, pero kayo po ang magdedesisyon sa final selling price niyo. Hindi po namin kayang mangako ng specific na kita - nakadepende po ito sa presyo niyo, sa dami ng mabebenta, at sa area niyo.', 'Gusto niyo po bang i-compute natin ang margin base sa selling price na naiisip niyo, para may malinaw kayong number?', array['Never guarantee an income figure, monthly or otherwise.', 'Never repeat another reseller’s earnings as an expected result.', 'Always frame computations as the customer’s own numbers, clearly marked as an example.']::text[], true, 'published')
on conflict (id) do update set
  slug = excluded.slug,
  objection = excluded.objection,
  translation = excluded.translation,
  category = excluded.category,
  frequency = excluded.frequency,
  acknowledge = excluded.acknowledge,
  clarify = excluded.clarify,
  address = excluded.address,
  close = excluded.close,
  pitfalls = excluded.pitfalls,
  claim_sensitive = excluded.claim_sensitive,
  status = excluded.status
;

commit;
